-- Validates the baked Forever snapshot generated by tools/build_seed.py.
-- Run from the addon folder: lua tests/seed_spec.lua

_G.NodeTaxiNS = {}
local chunk = assert(loadfile("data.lua"))
chunk("NodeTaxi", _G.NodeTaxiNS)
local seed = _G.NodeTaxiNS.SeedData
assert(seed, "data.lua did not define SeedData")

local checks, failures = 0, 0
local function check(name, condition, detail)
    checks = checks + 1
    if not condition then
        failures = failures + 1
        print("FAIL " .. name .. (detail and (" - " .. tostring(detail)) or ""))
    end
end

local function count(tbl)
    local zones, nodes = 0, 0
    for _, entry in pairs(tbl) do
        zones = zones + 1
        nodes = nodes + #(entry.keys or {})
    end
    return zones, nodes
end

local function validate(tbl, label)
    local bad = 0
    for zone, entry in pairs(tbl) do
        check(label .. " zone id " .. tostring(zone), type(zone) == "number" and zone > 0)
        check(label .. " keys/ids aligned in " .. tostring(zone),
            #(entry.keys or {}) == #(entry.ids or {}))
        for i = 1, #(entry.keys or {}) do
            local key = entry.keys[i]
            local x = math.floor(key / 1000000) / 10000
            local y = math.floor((key % 1000000) / 100) / 10000
            if x < 0 or x > 1 or y < 0 or y > 1 then
                bad = bad + 1
            end
            check(label .. " node id in " .. tostring(zone), type(entry.ids[i]) == "number")
        end
    end
    check(label .. " coordinates in range", bad == 0, bad)
end

check("seed has a version", type(seed.version) == "string" and #seed.version > 0)
local herbZones, herbNodes = count(seed.herbs)
local mineZones, mineNodes = count(seed.mines)

check("herb zone count", herbZones == 44, herbZones)
check("herb node count", herbNodes == 13332, herbNodes)
check("mine zone count", mineZones == 40, mineZones)
check("mine node count", mineNodes == 10486, mineNodes)

validate(seed.herbs, "herbs")
validate(seed.mines, "mines")

-- The Forever snapshot covers the new Zephras Isle and Riverglades zones.
check("Zephras Isle (2521) herbs", #(seed.herbs[2521].keys or {}) == 491, #(seed.herbs[2521].keys or {}))
check("Zephras Isle (2521) mines", #(seed.mines[2521].keys or {}) == 241, #(seed.mines[2521].keys or {}))
check("Riverglades (2548) herbs", #(seed.herbs[2548].keys or {}) == 100, #(seed.herbs[2548].keys or {}))

-- Specific node art is bundled and referenced by node id.
check("copper icon mapped", type(seed.icons[201]) == "string" and seed.icons[201]:find("Mine", 1, true) ~= nil)
check("peacebloom icon mapped", type(seed.icons[401]) == "string" and seed.icons[401]:find("Herb", 1, true) ~= nil)
for _, info in ipairs({ { 201, "Media/Mine/copper.tga", "copper.tga" }, { 401, "Media/Herb/peacebloom.tga", "peacebloom.tga" } }) do
    local nodeID, relative, leaf = info[1], info[2], info[3]
    local fh = io.open(relative, "rb")
    check("bundled icon file " .. relative, fh ~= nil)
    if fh then fh:close() end
    check("icon path for " .. nodeID, seed.icons[nodeID] and seed.icons[nodeID]:find(leaf, 1, true) ~= nil)
end

-- The snapshot must produce a usable route in a real zone (Elwynn Forest).
_G.NodeTaxiNS.SeedData = seed
dofile("route.lua")
local Route = _G.NodeTaxiNS.Route
local function decode(key)
    return math.floor(key / 1000000) / 10000, math.floor((key % 1000000) / 100) / 10000
end
local nodes = {}
for i = 1, #(seed.herbs[1429].keys or {}) do
    local x, y = decode(seed.herbs[1429].keys[i])
    nodes[#nodes + 1] = { x = x, y = y, kind = "herb", nodeID = seed.herbs[1429].ids[i] }
end
local plan = Route.Plan({
    start = { x = 0.30, y = 0.30 },
    dest = { x = 0.70, y = 0.70 },
    nodes = nodes,
    width = 3000,
    height = 2000,
    corridor = 300,
    maxNodes = 8,
    detour = 2.0,
})
check("Elwynn snapshot route exists", plan ~= nil)
check("Elwynn snapshot route has nodes", plan and #plan.nodes > 0, plan and #plan.nodes)
check("Elwynn snapshot route stays in budget", plan and plan.length <= plan.budget + 1e-6)
if plan then
    print(string.format("Elwynn sample: %d/%d nodes, %.0f yd (direct %.0f)",
        #plan.nodes, plan.inCorridor, plan.length, plan.direct))
end

print(string.format("%d checks, %d failure(s)", checks, failures))
if failures > 0 then
    os.exit(1)
end
